sys_script.script:
(function executeRule(current, previous) {
    var supplierSysId = current.getValue('supplier');

    if (!supplierSysId) {
        gs.warn('Recalculate Supplier Score: No supplier on evaluation ' +
            current.getUniqueValue() + ', skipping.');
        return;
    }

    try {
        var engine = new x_2056099_indust_0.SupplierScoringEngine();
        var result = engine.recalculate(supplierSysId);

        if (result.success) {
            gs.info('Recalculate Supplier Score: Scorecard updated for supplier ' +
                supplierSysId + ' — ' + result.overallScorePct + '/100 (' +
                result.overallRating + '/10), status=' + result.performanceStatus +
                '. Triggered by evaluation ' + current.getUniqueValue());
        } else {
            gs.error('Recalculate Supplier Score: Engine returned failure for supplier ' +
                supplierSysId + ': ' + (result.error || 'unknown error'));
        }
    } catch (e) {
        gs.error('Recalculate Supplier Score: Exception recalculating scorecard for ' +
            supplierSysId + ': ' + e.message);
    }
})(current, previous);
